[Sink(DestinationSystem = typeof(SchoolObjectModel))]
public class CourseSink : ISink<Course>
{
    private readonly ICourseService service;
    [ImportingConstructor]
    public CourseSink(ICourseService service) => this.service = service;

    public Course New() => new Course();
    public void Create(Course e) => this.service.Create(e);
    public Course Get(Course e) => this.service.Get(e.Code);
    public void Update(Course e) => this.service.Update(e);
    public void Delete(Course e) => this.service.Delete(e.Code);
}
